<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Etalase terkurasi elektronik dan perangkat IT."><title>TeknoTemu — Etalase Elektronik</title><style>:root{--ink:#1A4230;--muted:#1A4230aa;--cream:#EFE3CA;--paper:#EFE3CA;--lime:#F0402A;--line:#1A423033;--dark:#1A4230}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font:15px/1.5 Inter,system-ui,sans-serif}a,button{cursor:pointer}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.skip-link{position:absolute;left:16px;top:-50px;background:var(--ink);color:#EFE3CA;padding:10px 14px;border-radius:8px;z-index:20}.skip-link:focus{top:16px}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid var(--lime);outline-offset:3px}.header{height:76px;background:#EFE3CAdd;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:28px;padding:0 clamp(20px,5vw,76px);position:sticky;top:0;z-index:5;backdrop-filter:blur(12px)}.brand{color:var(--ink);font-size:22px;font-weight:850;letter-spacing:-1px}.brand span{color:var(--dark)}.search{display:flex;max-width:480px;flex:1;margin:auto}.search input{width:100%;border:1px solid var(--line);border-radius:24px 0 0 24px;padding:12px 18px;background:var(--paper);font:inherit}.search button{border:0;border-radius:0 24px 24px 0;background:var(--lime);width:48px;font-size:22px;cursor:pointer}.admin{color:var(--ink);border:1px solid var(--line);border-radius:20px;padding:8px 14px;text-decoration:none;font-weight:700;white-space:nowrap}.nav{display:flex;gap:22px;overflow:auto;padding:16px clamp(20px,5vw,76px);background:#EFE3CA;white-space:nowrap}.nav a{color:var(--muted);text-decoration:none}.nav a:hover{color:var(--ink);font-weight:700}.hero{position:relative;background:#1A4230;color:#EFE3CA;min-height:390px;padding:54px clamp(24px,7vw,96px);display:grid;grid-template-columns:minmax(0,1fr) minmax(300px,420px);gap:48px;align-items:center;overflow:hidden;border-radius:0 0 28px 28px}.hero:before{content:'PROMO';position:absolute;right:31%;top:50%;color:#F0402A;font-size:clamp(72px,11vw,140px);font-weight:900;line-height:1;transform:translateY(-50%) rotate(-12deg);opacity:.45;pointer-events:none}.hero>div:first-child{position:relative;z-index:1;max-width:560px}.hero h1{color:#EFE3CA;max-width:540px}.hero p:not(.eyebrow){color:#EFE3CA;max-width:430px}.hero .eyebrow{display:inline-flex;background:#EFE3CA;color:#1A4230;padding:7px 11px;border-radius:999px;letter-spacing:.5px}.hero .button{background:#F0402A;color:#1A4230;box-shadow:0 8px 18px #1A423040}.hero .art{width:min(100%,420px);margin:0 auto;z-index:1}.hero-slides{position:relative;aspect-ratio:4/3;overflow:hidden;border-radius:18px;background:#EFE3CA;box-shadow:0 20px 45px #0b211860}.hero-slide{position:absolute;inset:0;opacity:0;transition:opacity .5s ease}.hero-slide.active{opacity:1}.hero-slide img{width:100%;height:100%;object-fit:cover;display:block}.hero-dots{display:flex;justify-content:center;align-items:center;gap:2px;margin-top:12px}.hero-dot{width:10px;height:10px;margin:6px;padding:0;border:0;border-radius:999px;background:#EFE3CA66;transition:width .2s,background .2s}.hero-dot.active{width:26px;background:#F0402A}.eyebrow{font-size:11px;letter-spacing:2px;color:#F0402A;font-weight:800;margin:0 0 12px}.hero h1{font-size:clamp(42px,6vw,78px);line-height:.98;letter-spacing:-4px;margin:0 0 24px}.hero h1 em{color:var(--lime);font-style:normal}.hero p:not(.eyebrow){color:#1A4230aa;max-width:410px;margin-bottom:28px}.button{display:inline-block;background:var(--lime);color:var(--ink);padding:13px 21px;border-radius:24px;text-decoration:none;font-weight:800}main>section:not(.hero){max-width:1180px;margin:auto;padding:58px clamp(20px,5vw,76px) 0}.section-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:22px}.section-head h2{font-size:32px;letter-spacing:-1.5px;margin:0}.collections{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.collections a{background:#EFE3CA;border:1px solid var(--line);border-radius:15px;padding:22px;color:var(--ink);text-decoration:none;display:grid;gap:4px}.collections a:first-child{background:#EFE3CA}.collections small,.meta{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card{background:#EFE3CA;border:1px solid var(--line);border-radius:14px;overflow:hidden;position:relative}.card img{width:100%;aspect-ratio:1;object-fit:cover;display:block;background:#EFE3CA}.info{padding:15px}.info h3{font-size:15px;line-height:1.3;margin:0 0 8px;min-height:40px}.price{font-weight:850;font-size:18px;margin:8px 0 2px}.spec{color:#1A4230aa;font-size:12px}.badge{position:absolute;top:11px;left:11px;background:var(--lime);padding:4px 8px;border-radius:6px;font-size:10px;font-weight:900}footer{margin-top:80px;padding:28px clamp(20px,5vw,76px);background:var(--dark);color:#EFE3CA;display:flex;gap:28px;flex-wrap:wrap;font-size:12px}footer b{color:var(--lime)}footer span{color:#1A4230aa}@media(max-width:1050px){.grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.header{height:auto;flex-wrap:wrap;padding:15px 20px;gap:10px}.search{order:3;flex-basis:100%}.hero{grid-template-columns:1fr;padding:52px 24px;min-height:500px;gap:18px}.collections{grid-template-columns:1fr}.grid{grid-template-columns:repeat(2,1fr);gap:10px}.info{padding:11px}.nav{padding:12px 20px}main>section:not(.hero){padding-top:44px}}</style></head><body>@include('partials.site-header')<style>.hero{background:#1A4230!important;min-height:430px!important;border-radius:0!important;padding:72px clamp(24px,8vw,120px)!important}.hero:before{content:'01 / KATALOG'!important;color:#1A4230!important;right:7%!important;top:18%!important;font-size:clamp(70px,10vw,150px)!important;transform:rotate(90deg)!important;letter-spacing:-8px}.hero h1{font-size:clamp(46px,6vw,82px)!important;letter-spacing:-4px!important;max-width:650px!important}.hero h1 em{color:#F0402A!important}.hero p:not(.eyebrow){font-size:17px;line-height:1.65;color:#EFE3CA99!important}.hero .eyebrow{background:#F0402A!important;color:#1A4230!important;border-radius:6px!important;font-weight:900}.hero .button{background:#EFE3CA!important;color:#1A4230!important;border-radius:8px!important;padding:14px 20px!important}.hero .art{opacity:1}.hero-slides{border-radius:12px!important;box-shadow:0 24px 50px #0b211870}@media(prefers-reduced-motion:reduce){.hero-slide{transition:none}}.section-head h2{font-size:36px!important;letter-spacing:-2px!important}.collections a{border:0!important;border-radius:12px!important;padding:26px!important;min-height:108px;transition:transform .2s,box-shadow .2s}.collections a:hover{transform:translateY(-4px);box-shadow:0 12px 25px #1A423020}.collections a:first-child{background:#EFE3CA!important}.grid{gap:20px!important}.card{border:0!important;border-radius:12px!important;box-shadow:0 8px 24px #1A423014!important;transition:transform .2s,box-shadow .2s}.card:hover{transform:translateY(-5px);box-shadow:0 16px 30px #1A423026!important}.card img{background:#EFE3CA!important;aspect-ratio:1.08!important}.info{padding:17px!important}.info h3{font-size:16px!important}.price{color:#1A4230;font-size:20px!important}.badge{background:#F0402A!important;border-radius:5px!important}footer{background:#1A4230!important;border-radius:0!important;padding-top:38px!important;padding-bottom:38px!important}footer div{display:grid;gap:5px;min-width:180px}footer strong{color:#EFE3CA;font-size:13px}footer b{font-size:21px}footer p{margin:4px 0;color:#EFE3CA99}.collections a.active{background:#F0402A!important;color:#1A4230!important;box-shadow:0 12px 25px #1A423030}</style><main><section class="hero"><div><p class="eyebrow">KURASI ELEKTRONIK & IT</p><h1>Temukan perangkat<br><em>yang tepat.</em></h1><p>Pilihan terkurasi dengan spesifikasi jelas. Bandingkan dulu, beli di marketplace pilihan Anda.</p><a class="button" href="#products">Lihat pilihan</a></div><div class="art" id="heroSlider" role="region" aria-label="Foto produk pilihan"><div class="hero-slides" id="heroSlides"></div><div class="hero-dots" id="heroDots" aria-label="Pilih foto produk"></div></div></section><section><div class="section-head"><div><p class="eyebrow">PILIH SESUAI KEBUTUHAN</p><h2>Koleksi pilihan</h2></div></div><div class="collections">@foreach($collections as $collection)<a href="#products" data-collection="{{ $collection->name }}"><b>{{ $collection->name }}</b><small>{{ $collection->description }}</small></a>@endforeach</div></section><section id="products"><div class="section-head"><div><p class="eyebrow">KATALOG TERKURASI</p><h2>Produk pilihan</h2></div></div><div class="grid" id="grid"><p>Memuat produk...</p></div></section></main>@include('partials.site-footer')<script>const grid=document.getElementById('grid'),query=document.getElementById('query'),heroSlider=document.getElementById('heroSlider'),heroSlides=document.getElementById('heroSlides'),heroDots=document.getElementById('heroDots');let products=[],activeCategory='',activeCollection='',heroIndex=0,heroTimer;document.querySelectorAll('[data-category]').forEach(a=>a.onclick=()=>{activeCategory=a.dataset.category;activeCollection='';document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===a));render()});document.querySelectorAll('[data-collection]').forEach(a=>a.onclick=()=>{activeCollection=a.dataset.collection;activeCategory='';document.querySelectorAll('[data-collection]').forEach(x=>x.classList.toggle('active',x===a));document.querySelectorAll('[data-category]').forEach(x=>x.classList.remove('active'));render();document.getElementById('products').scrollIntoView({behavior:'smooth'})});const money=n=>'Rp '+Number(n).toLocaleString('id-ID');function render(){const q=query.value.toLowerCase();const list=products.filter(p=>(!activeCategory||p.category===activeCategory)&&(!activeCollection||p.collection_name===activeCollection)&&`${p.name} ${p.brand} ${p.category}`.toLowerCase().includes(q));grid.innerHTML=list.length?list.map(p=>`<article class="card"><a href="/products/${p.slug}"><img src="${p.image_url||'https://placehold.co/600x600/e5eadb/17251f?text=Produk'}" alt="${p.name}" loading="lazy"></a>${p.is_top?'<span class="badge">TOP</span>':''}<div class="info"><h3>${p.name}</h3><div class="meta">${p.brand||''} · ${Number(p.sold_count||0).toLocaleString('id-ID')} terjual</div><div class="price">${money(p.price_idr)}</div><div class="spec">${p.spec||''}</div></div></article>`).join(''):'<p>Produk tidak ditemukan.</p>'}function showHeroSlide(index){const slides=[...heroSlides.children],dots=[...heroDots.children];if(!slides.length)return;heroIndex=(index+slides.length)%slides.length;slides.forEach((el,i)=>{el.classList.toggle('active',i===heroIndex);el.setAttribute('aria-hidden',i!==heroIndex)});dots.forEach((el,i)=>{el.classList.toggle('active',i===heroIndex);if(i===heroIndex)el.setAttribute('aria-current','true');else el.removeAttribute('aria-current')})}function startHeroTimer(){clearInterval(heroTimer);heroTimer=setInterval(()=>showHeroSlide(heroIndex+1),4000)}function initHeroSlider(){const photos=products.slice(0,5).map(p=>({src:p.image_url||'https://placehold.co/800x600/e5eadb/17251f?text=Produk',name:p.name}));while(photos.length<5)photos.push({src:'https://placehold.co/800x600/e5eadb/17251f?text=Produk+'+(photos.length+1),name:'Produk '+(photos.length+1)});heroSlides.innerHTML=photos.map((p,i)=>`<div class="hero-slide${i?'':' active'}"${i?' aria-hidden="true"':''}><img src="${p.src}" alt="Foto ${p.name}" loading="${i?'lazy':'eager'}"></div>`).join('');heroDots.innerHTML=photos.map((_,i)=>`<button type="button" class="hero-dot${i?'':' active'}" data-slide="${i}" aria-label="Foto produk ${i+1}"${i?'':' aria-current="true"'}></button>`).join('');heroDots.querySelectorAll('[data-slide]').forEach(btn=>btn.onclick=()=>{showHeroSlide(Number(btn.dataset.slide));startHeroTimer()});heroSlider.onmouseenter=()=>clearInterval(heroTimer);heroSlider.onmouseleave=startHeroTimer;heroSlider.onfocusin=()=>clearInterval(heroTimer);heroSlider.onfocusout=startHeroTimer;if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&!heroSlider.matches(':hover'))startHeroTimer()}
fetch('/api/products').then(r=>r.json()).then(d=>{products=d.data||d;render();initHeroSlider()}).catch(()=>{grid.innerHTML='<p>Produk belum tersedia.</p>';initHeroSlider()});query.oninput=render;</script></body></html>